#include "route_heatmap.h"
#include "first_barrier_contact.h"
#include "jolt_runtime.h"
#include <iostream>
#include <numeric>
using namespace rs3d;
namespace {
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
void route(){
    RouteAccumulator a(0,4,0,4,4);RouteAccumulator::Visits v;
    a.visit(v,{.5,.5,100},{3.5,.5,200});a.visit(v,{3.5,.5,-10},{.5,.5,10});a.visit(v,{.5,.5,20},{.5,.5,20});check(v.size()==4,"route repeats/high altitude counted incorrectly");
    a.finish(v,true);a.finish({},true);auto p=a.probability(1,false);check(!p.value&&p.lower==.25&&p.upper==.75,"partial route bounds");a.finish(v,false);check(a.completed()==2,"failed route counted");a.finish(v,true);a.finish({},true);p=a.probability(2,true);check(p.value==.5&&p.lower==.5&&p.upper==.5,"exact route probability");
    RouteAccumulator edge(0,3,0,3,1);RouteAccumulator::Visits q;edge.visit(q,{-1,-1,7},{3,3,100});check(q.size()==3,"diagonal boundary/corner ownership");edge.visit(q,{3,3,0},{0,0,0});check(q.size()==3,"reverse corner segment differs");
    RouteAccumulator all(0,200,-20,20,1);RouteAccumulator::Visits wide;all.visit(wide,{10,0,100},{180,0,90});all.finish(wide,true);check(wide.size()==171,"full path outside toe area missing");check(all.probability(all.hits().at(*all.grid().cellAt({10,0,.5})),true).value==1,"t0 release cell missing");std::cout<<"H1/H2 full XY exact DDA, release, altitude, repeats and bounds PASS\n";
}
SolvedContact candidate(Vec3 local,unsigned sub=1,ContactSource source=ContactSource::constraint){SolvedContact r;r.object1=rockObjectId;r.object2=barrierObjectId;r.step=0;r.substep=sub;r.timeLower=(sub-1)*.0005;r.timeUpper=sub*.0005;r.source=source;r.retained=true;r.gap=.01;r.normalImpulse=10;r.normal={1,0,0};r.pose2.center={10,7,5};r.pose2.rotation=Quaternion::fromAxisAngle({0,0,1},.7);r.point2=r.pose2.center+r.pose2.rotation.matrix()*local;r.point1=r.point2-r.normal*r.gap;return r;}
void contacts(){
    BarrierSettings b;b.enabled=true;b.width=2.3;b.height=1.7;b.thickness=.2;FirstBarrierContactCollector c(1,b,.0002,100);
    std::vector<SolvedContact> points{candidate({-.1,-.2,0}),candidate({-.1,.2,0}),candidate({-.1,.2,0}),candidate({-.1,1,0},2)};c.observe(points);auto first=c.event();check(first.status==FirstContactStatus::hit&&first.points.size()==3&&std::abs(first.u-1.15)<1e-12&&std::abs(first.v-.85)<1e-12,"first simultaneous representative");c.observe({candidate({-.1,-1,0},3)});check(c.event().u==first.u,"second collision replaced first event");c.finish(StopReason::resting);
    std::reverse(points.begin(),points.end());FirstBarrierContactCollector reverse(1,b,.0002,100);reverse.observe(points);check(reverse.event().u==first.u&&reverse.event().cell==first.cell,"input order changed contact grouping");
    for(auto p:{Vec3{-.1,-1.15,-.85},Vec3{.1,1.15,.85},Vec3{0,1.15,.1},Vec3{0,0,.85}}){FirstBarrierContactCollector corner(1,b,.0002,100);corner.observe({candidate(p)});check(corner.event().status==FirstContactStatus::hit,"boundary/side/corner point rejected");auto e=corner.event();check(norm(e.points[0].barrier.center+e.points[0].barrier.rotation.matrix()*e.points[0].local-e.points[0].world)<1e-12,"local/world event transform mismatch");}
    FirstBarrierContactCollector outside(1,b,.0002,100);outside.observe({candidate({-.1,2,0})});check(outside.event().status==FirstContactStatus::unresolved,"outside point silently clamped");
    FirstBarrierContactCollector miss(1,b,.0002,100);auto spec=candidate({-.1,0,0});spec.normalImpulse=0;miss.observe({spec});auto discard=spec;discard.source=ContactSource::ccdDiscarded;discard.retained=false;miss.observe({discard});auto terrain=spec;terrain.object1=terrainObjectId;terrain.gap=0;miss.observe({terrain});miss.finish(StopReason::downstream);check(miss.event().status==FirstContactStatus::noHit,"speculative/discarded/nonrock candidate counted");
    FirstBarrierContactCollector lost(1,b,.0002,100);lost.observe({},true);lost.observe({candidate({-.1,0,0})});check(lost.event().status==FirstContactStatus::unresolved,"later hit claims first after missing earlier observations");
    FirstContactAccumulator total(b,10);auto e=c.event();e.cell=0;for(int i=0;i<3;++i)total.finish(e);e.cell=1;total.finish(e);for(int i=0;i<2;++i)total.finish(miss.event());auto p=total.probability(3,false);check(total.hitTrials()==4&&total.missTrials()==2&&total.unknown()==4&&!p.value&&p.lower==.3&&p.upper==.7&&!total.conditional(3,false),"partial contact denominators");for(int i=0;i<4;++i)total.finish(miss.event());check(total.probability(3,true).value==.3&&total.probability(1,true).value==.1&&total.conditional(3,true)==.75&&total.conditional(1,true)==.25,"complete contact denominators");
    for(auto n:{2,100,300}){FirstContactAccumulator small(b,n);check(small.probability(0,false).lower==0,"small sample hidden");}
    std::cout<<"C1/C2/C3/C4 point grouping, moving frame, corners, unknowns and two denominators PASS\n";
}
Polyhedron box(double x=.5){std::vector<Vec3> v;for(int a:{-1,1})for(int b:{-1,1})for(int c:{-1,1})v.push_back({a*x,b*.5,c*.5});return convexPolyhedron(v);}
void physical(){for(int mode=0;mode<7;++mode){PhysicsScene s;s.shape=box(mode==4||mode==5?.005:.5);s.radius=1;s.dynamics.gravity={};s.dynamics.density=2000;s.dynamics.dragCoefficient=0;s.dynamics.rollingCoefficient=0;s.barrier.enabled=true;s.barrier.center={10,0,5};s.barrier.width=6;s.barrier.height=6;s.barrier.friction=0;s.barrier.restitution=.9;s.barrier.elastic=mode==2||mode==5;s.initial.shapeOrigin={8.013,0,5};s.initial.velocity={50,0,0};
    if(mode==0){s.initial.shapeOrigin.x=9.39995;s.initial.velocity.x=.01;}if(mode==3){s.initial.shapeOrigin={9.39,0,5};s.initial.velocity={0,20,0};}if(mode==4)s.initial.shapeOrigin.x=9.873;if(mode==5){s.initial.shapeOrigin.x=9.80;s.initial.velocity.x=500;}if(mode==6){TerrainSettings t;t.type=TerrainType::flat;t.flatLength=30;t.width=20;s.terrain=std::make_shared<TerrainMesh>(buildTerrain(t));s.initial.shapeOrigin.z=.5;s.barrier.center.z=3;s.dynamics.gravity={0,0,-9.81};}
    Trial trial(s,{1,true});auto d=trial.diagnostics();FirstBarrierContactCollector collector(1,s.barrier,d.slop,d.mass);for(int i=0;i<150;++i){trial.step();collector.observe(trial.observations(),trial.diagnostics().observerOverflow);}collector.finish(StopReason::downstream);const auto&e=collector.event();std::cout<<"real first mode="<<mode<<" status="<<firstContactStatusName(e.status)<<" reason="<<e.reason<<" points="<<e.points.size()<<" interval="<<e.timeLower<<':'<<e.timeUpper<<'\n';check(e.status==(mode==3?FirstContactStatus::noHit:FirstContactStatus::hit),"real first contact not confirmed");if(mode==1)check(e.points[0].gap>d.slop&&e.points[0].method==ContactMethod::solvedConstraint,"ordinary positive-gap response lost");if(mode==4||mode==5)check(e.points[0].method==ContactMethod::resolvedCcd,"real CCD first event lost");}
}
void precision(){
    for(bool elastic:{false,true}){FirstContactEvent previous;for(double dt:{.002,.001}){PhysicsScene s;s.shape=box();s.radius=1;s.dynamics.gravity={};s.dynamics.density=2000;s.dynamics.dragCoefficient=0;s.dynamics.rollingCoefficient=0;s.barrier.enabled=true;s.barrier.elastic=elastic;s.barrier.center={10,0,5};s.barrier.width=6;s.barrier.height=6;s.barrier.friction=0;s.barrier.restitution=.9;s.initial.shapeOrigin={8.013,0,5};s.initial.velocity={50,0,0};Trial trial(s,{1,true});auto d=trial.diagnostics();FirstBarrierContactCollector collector(1,s.barrier,d.slop,d.mass);for(int i=0;i<int(.1/dt);++i){trial.step(dt);collector.observe(trial.observations(),trial.diagnostics().observerOverflow);}collector.finish(StopReason::downstream);auto e=collector.event();check(e.status==FirstContactStatus::hit&&!e.points.empty(),"smaller-dt ordinary collision not confirmed");check(e.timeUpper-e.timeLower<=dt/4+1e-8,"event does not use actual substep interval");std::cout<<"C3 dt="<<dt<<" elastic="<<elastic<<" interval="<<e.timeLower<<':'<<e.timeUpper<<" gap="<<e.points[0].gap<<" impulse="<<e.points[0].impulse<<" method="<<contactMethodName(e.points[0].method)<<" local="<<e.u<<','<<e.v<<'\n';if(previous.status==FirstContactStatus::hit)check(e.timeUpper-e.timeLower<previous.timeUpper-previous.timeLower,"smaller dt did not improve declared resolution");previous=e;}}
}

}
int main(){try{JoltRuntime runtime;std::cout<<std::unitbuf;route();contacts();physical();precision();std::cout<<"PASS analysis tests\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
